        size: '680 B',
        command: 'YarnRMClient.unregister(FinalApplicationStatus.SUCCEEDED, "", trackingUrl)',
        payload: 'FinishApplicationMasterRequest(finalStatus=SUCCEEDED, diagnostics="")',
