        to: 'spark-driver',
        channel: 'internal',
        protocol: 'In-JVM Initialization',
        port: 'driver-1 in-JVM',
        label: 'Init SparkEnv & sched',
        info: 'Driver JVM creates SparkContext + SparkEnv (NettyRpcEnv :41000, BlockManager :41001), Spark UI (:4040), and schedulers.',
        size: 'in-memory',
        command: 'SparkContext.<init> -> createSparkEnv() && createTaskScheduler()',
        payload: 'Driver JVM endpoints registered: CoarseGrainedScheduler, YarnScheduler, HeartbeatReceiver',
        fields: [
          { name: 'sparkRpcPort', value: '41000' },
          { name: 'blockMgrPort', value: '41001' },
          { name: 'sparkUiPort', value: '4040' },
        ],
        senderState: 'Executing SparkContext constructor on Driver thread',
