        channel: 'internal',
        protocol: 'In-JVM Job Submission',
        port: 'driver-1 in-JVM',
        label: 'runJob(rdd, cleanFn)',
        info: `Verifies !stopped, captures callSite (${v.sourceFile}), runs ClosureCleaner.clean, and hands job + local properties to DAGScheduler.`,
        size: 'in-memory',
