        protocol: 'In-JVM ThreadPool Submit',
        port: 'worker-a in-JVM',
        label: 'submit(TaskRunner 41)',
        info: 'Inserts TaskRunner 41 into runningTasks, checks killMarks (none for 41; 44 aborts pre-compute), and submits to pool.',
        size: 'in-memory',
