  'flow-python-udf-boundary': buildFlowPythonUdfBoundary,
  'comp-spark-submit': buildCompSparkSubmit,
  'comp-yarn-client': buildCompYarnClient,
  'comp-application-master': buildCompApplicationMaster,
  'comp-spark-driver': buildCompSparkDriver,
  'comp-spark-session': buildCompSparkSession,
  'comp-spark-context': buildCompSparkContext,
  'comp-executor': buildCompExecutor,
  'comp-rdd-cache': buildCompRddCache,
  'scenario-01': buildScenario01,
  'scenario-02': buildScenario02,
  'scenario-03': buildScenario03,
